<div class="page-actions"><div><p class="mb-0">Multi-warehouse inventory, stock validation, adjustment, transfer, low stock, dan movement history.</p></div><div class="d-flex gap-2"><button class="btn btn-outline-primary" data-bs-toggle="modal" data-bs-target="#adjustModal">Adjust Stock</button><button class="btn btn-outline-primary" data-bs-toggle="modal" data-bs-target="#transferModal">Transfer</button><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#itemModal">New Item</button></div></div>
<div class="row g-3 mb-3"><div class="col-lg-7"><div class="card-panel"><h3 class="h6 mb-3">Items</h3><div class="table-responsive"><table class="table datatable"><thead><tr><th>SKU</th><th>Item</th><th>Category</th><th>Total Stock</th><th>Min</th><th>Selling</th><th>Label</th></tr></thead><tbody><?php foreach($items as $i): ?><tr><td><?= e($i['sku']) ?></td><td><strong><?= e($i['item_name']) ?></strong><small class="d-block text-secondary"><?= e($i['brand']??'') ?></small></td><td><?= e($i['category']??'-') ?></td><td><span class="status-badge <?= $i['stock']<=$i['minimum_stock']?'danger':'success' ?>"><?= e($i['stock'].' '.$i['unit']) ?></span></td><td><?= e($i['minimum_stock']) ?></td><td><?= e(money($i['selling_price'])) ?></td><td><a class="btn btn-sm btn-light" href="<?= url('/inventory/'.$i['id'].'/barcode') ?>"><i class="bi bi-upc-scan"></i></a></td></tr><?php endforeach; ?></tbody></table></div></div></div><div class="col-lg-5"><div class="card-panel"><h3 class="h6 mb-3">Warehouse Balances</h3><div class="stock-list"><?php foreach($balances as $b): ?><div><span><strong><?= e($b['item_name']) ?></strong><small><?= e($b['warehouse_name']) ?></small></span><span class="status-badge <?= $b['quantity']<=$b['minimum_stock']?'danger':'success' ?>"><?= e($b['quantity'].' '.$b['unit']) ?></span></div><?php endforeach; ?></div></div></div></div>
<div class="card-panel"><h3 class="h6 mb-3">Recent Stock Movements</h3><div class="table-responsive"><table class="table"><thead><tr><th>Date</th><th>Item</th><th>Warehouse</th><th>Type</th><th>Qty</th><th>Reference</th><th>By</th></tr></thead><tbody><?php foreach($movements as $m): ?><tr><td><?= e($m['created_at']) ?></td><td><?= e($m['sku'].' · '.$m['item_name']) ?></td><td><?= e($m['warehouse_name']) ?></td><td><?= e($m['movement_type']) ?></td><td class="<?= $m['quantity']<0?'text-danger':'text-success' ?>"><?= e($m['quantity']) ?></td><td><?= e(($m['reference_type']??'-').' #'.($m['reference_id']??'-')) ?></td><td><?= e($m['user_name']??'System') ?></td></tr><?php endforeach; ?></tbody></table></div></div>
<div class="modal fade" id="itemModal"><div class="modal-dialog modal-lg"><form class="modal-content ajax-form" method="post" action="<?= url('/inventory') ?>"><?= csrf_field() ?><div class="modal-header"><h5>New Item</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body row g-3"><div class="col-md-4"><label class="form-label">SKU</label><input class="form-control" name="sku"></div><div class="col-md-8"><label class="form-label">Item Name</label><input class="form-control" name="item_name" required></div><div class="col-md-4"><label class="form-label">Category</label><input class="form-control" name="category"></div><div class="col-md-4"><label class="form-label">Brand</label><input class="form-control" name="brand"></div><div class="col-md-4"><label class="form-label">Unit</label><input class="form-control" name="unit" value="pcs"></div><div class="col-md-4"><label class="form-label">Purchase Price</label><input type="number" step="0.01" class="form-control" name="purchase_price"></div><div class="col-md-4"><label class="form-label">Selling Price</label><input type="number" step="0.01" class="form-control" name="selling_price"></div><div class="col-md-4"><label class="form-label">Minimum Stock</label><input type="number" step="0.01" class="form-control" name="minimum_stock"></div><div class="col-md-6"><label class="form-label">Barcode</label><input class="form-control" name="barcode"></div><div class="col-md-6"><label class="form-label">Location</label><input class="form-control" name="location"></div></div><div class="modal-footer"><button class="btn btn-primary">Save Item</button></div></form></div></div>
<div class="modal fade" id="adjustModal"><div class="modal-dialog"><form class="modal-content ajax-form" method="post" action="<?= url('/inventory/adjust') ?>"><?= csrf_field() ?><div class="modal-header"><h5>Stock Adjustment</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><label class="form-label">Warehouse</label><select class="form-select mb-2" name="warehouse_id" required><?php foreach($warehouses as $w): ?><option value="<?= $w['id'] ?>"><?= e($w['name']) ?></option><?php endforeach; ?></select><label class="form-label">Item</label><select class="form-select mb-2" name="item_id" required><?php foreach($items as $i): ?><option value="<?= $i['id'] ?>"><?= e($i['sku'].' · '.$i['item_name']) ?></option><?php endforeach; ?></select><label class="form-label">New Quantity</label><input type="number" step="0.01" min="0" class="form-control mb-2" name="quantity" required><label class="form-label">Reason</label><input class="form-control" name="notes"></div><div class="modal-footer"><button class="btn btn-primary">Apply Adjustment</button></div></form></div></div>
<div class="modal fade" id="transferModal"><div class="modal-dialog"><form class="modal-content ajax-form" method="post" action="<?= url('/inventory/transfer') ?>"><?= csrf_field() ?><div class="modal-header"><h5>Stock Transfer</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><label class="form-label">From</label><select class="form-select mb-2" name="from_warehouse_id" required><?php foreach($warehouses as $w): ?><option value="<?= $w['id'] ?>"><?= e($w['name']) ?></option><?php endforeach; ?></select><label class="form-label">To</label><select class="form-select mb-2" name="to_warehouse_id" required><?php foreach($warehouses as $w): ?><option value="<?= $w['id'] ?>"><?= e($w['name']) ?></option><?php endforeach; ?></select><label class="form-label">Item</label><select class="form-select mb-2" name="item_id" required><?php foreach($items as $i): ?><option value="<?= $i['id'] ?>"><?= e($i['sku'].' · '.$i['item_name']) ?></option><?php endforeach; ?></select><label class="form-label">Quantity</label><input class="form-control" type="number" step="0.01" min="0.01" name="quantity" required></div><div class="modal-footer"><button class="btn btn-primary">Transfer Stock</button></div></form></div></div>
